create table if not exists public.items (id text primary key, name text not null, slot text not null check (slot in ('head','body','legs','feet','cape','weapon','offhand','neck','ring')), rarity text not null check (rarity in ('comum','raro','épico','lendário')), price int not null default 0, descr text not null default '', look jsonb not null default '{}', starter boolean not null default false);
alter table public.items enable row level security;
drop policy if exists "itens: ler" on public.items;
create policy "itens: ler" on public.items for select to authenticated using (true);
create table if not exists public.inventory (user_id uuid not null references auth.users(id) on delete cascade, item_id text not null references public.items(id), acquired_at timestamptz not null default now(), primary key (user_id, item_id));
alter table public.inventory enable row level security;
drop policy if exists "inventario: ler o meu" on public.inventory;
create policy "inventario: ler o meu" on public.inventory for select to authenticated using (user_id = auth.uid());
create table if not exists public.characters (user_id uuid primary key references auth.users(id) on delete cascade, skin text not null default '#e0b48a', hair int not null default 0 check (hair between 0 and 5), hair_color text not null default '#4a3020', equip jsonb not null default '{}', starter boolean not null default false, updated_at timestamptz not null default now());
alter table public.characters enable row level security;
drop policy if exists "personagens: ler" on public.characters;
create policy "personagens: ler" on public.characters for select to authenticated using (true);
revoke insert, update, delete on public.items from anon, authenticated;
revoke insert, update, delete on public.inventory from anon, authenticated;
revoke insert, update, delete on public.characters from anon, authenticated;
create or replace function public.my_character() returns jsonb language plpgsql security definer set search_path = public as $$ declare c characters%rowtype; begin if auth.uid() is null then raise exception 'login necessário'; end if; insert into characters (user_id) values (auth.uid()) on conflict do nothing; select * into c from characters where user_id = auth.uid(); return jsonb_build_object('skin', c.skin, 'hair', c.hair, 'hair_color', c.hair_color, 'equip', c.equip, 'starter', c.starter, 'inv', coalesce((select jsonb_agg(item_id order by acquired_at) from inventory where user_id = auth.uid()), '[]'::jsonb)); end $$;
create or replace function public.claim_starter() returns jsonb language plpgsql security definer set search_path = public as $$ begin perform my_character(); if (select starter from characters where user_id = auth.uid()) then raise exception 'kit já recebido'; end if; insert into inventory (user_id, item_id) select auth.uid(), id from items where starter on conflict do nothing; update characters set starter = true, updated_at = now() where user_id = auth.uid(); return my_character(); end $$;
create or replace function public.set_appearance(skin text, hair int, hair_color text) returns jsonb language plpgsql security definer set search_path = public as $$ begin perform my_character(); if not (skin = any (array['#f0c8a0','#e0b48a','#c98f63','#8d5a3b','#5a3a28'])) then raise exception 'tom de pele inválido'; end if; if not (hair_color = any (array['#1c1824','#4a3020','#8a5a2a','#c9a24a','#d8d8e0','#a8421e'])) then raise exception 'cor de cabelo inválida'; end if; if hair is null or hair < 0 or hair > 5 then raise exception 'estilo de cabelo inválido'; end if; update characters set skin = set_appearance.skin, hair = set_appearance.hair, hair_color = set_appearance.hair_color, updated_at = now() where user_id = auth.uid(); return my_character(); end $$;
create or replace function public.equip_item(iid text) returns jsonb language plpgsql security definer set search_path = public as $$ declare s text; begin select slot into s from items where id = iid; if s is null then raise exception 'item inexistente'; end if; if not exists (select 1 from inventory where user_id = auth.uid() and item_id = iid) then raise exception 'você não possui este item'; end if; perform my_character(); update characters set equip = equip || jsonb_build_object(s, iid), updated_at = now() where user_id = auth.uid(); return my_character(); end $$;
create or replace function public.unequip_slot(slot text) returns jsonb language plpgsql security definer set search_path = public as $$ begin if not (slot = any (array['head','body','legs','feet','cape','weapon','offhand','neck','ring'])) then raise exception 'slot inválido'; end if; perform my_character(); update characters set equip = equip - unequip_slot.slot, updated_at = now() where user_id = auth.uid(); return my_character(); end $$;
create or replace function public.admin_grant_item(uid uuid, iid text) returns jsonb language plpgsql security definer set search_path = public as $$ begin if not is_admin() then raise exception 'acesso negado'; end if; if not exists (select 1 from items where id = iid) then raise exception 'item inexistente'; end if; insert into inventory (user_id, item_id) values (uid, iid) on conflict do nothing; return jsonb_build_object('ok', true); end $$;
